var rawTitle = heading ? heading.textContent.trim() : '';
var title = rawTitle.match(/^(.*?) — (\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2})$/);
if (!title) {
  var local = rawTitle.match(/^(.*?) — (\d{1,2}) (\S+) (\d{4}) (\d{2}):(\d{2})$/);
  var months = {ocak:1,şubat:2,mart:3,nisan:4,mayıs:5,haziran:6,temmuz:7,ağustos:8,eylül:9,ekim:10,kasım:11,aralık:12};
  if (local) {
    var month = months[local[3].toLocaleLowerCase('tr-TR')];
    if (month) title = [local[0],local[1],local[4],String(month).padStart(2,'0'),local[2].padStart(2,'0'),local[5],local[6]];
  }
}

